import Canvas2D from '../base/Canvas2D';
import random from '../utils/random';
import { mapRange } from '../utils/math';

// tweakable params
const PARAMS = {
  timeScale: 0.2,
  numLines: 30,
  lineSegments: 250,
  amplitude: 0.5,
  frequencyMax: 0.0035,
  frequencyMin: 0.0015,
  noiseOffset: 0.02,
};

// uncomment to create a noise instance
const rand = random();
const palette = ['#590212', '#D9415D', '#F2507B', '#0D0D0D'];

export default class NoiseLines2 extends Canvas2D {
  constructor(options) {
    super(options);

    this.pane.addInput(PARAMS, 'timeScale', { min: 0, max: 1 });
    this.pane.addInput(PARAMS, 'numLines', { min: 1, max: 50, step: 1 });
    this.pane.addInput(PARAMS, 'lineSegments', { min: 2, max: 500, step: 1 });
    this.pane.addInput(PARAMS, 'noiseOffset', { min: 0, max: 0.3 });
    this.pane.addInput(PARAMS, 'frequencyMax', { min: 0, max: 0.01 });
    this.pane.addInput(PARAMS, 'frequencyMin', { min: 0, max: 0.01 });
    this.pane.addInput(PARAMS, 'amplitude', { min: 0, max: 1 });
    this.pane
      .addButton({
        title: 'Generate',
      })
      .on('click', () => {
        this.createLines();
      });

    this.createLines();

    this.start();
  }

  createLines() {
    this.lines = [];

    for (let i = 0; i < PARAMS.numLines; i++) {
      this.lines.push(this.createLine());
    }
  }

  createLine() {
    const dist = this.width / PARAMS.lineSegments + 1;
    const line = {
      points: [],
      color: rand.pick(palette),
      width: rand.range(0.1, 0.5),
    };
    for (let i = 0; i < PARAMS.lineSegments; i++) {
      line.points.push({
        x: i * dist,
        y: this.centerY,
      });
    }
    return line;
  }

  onMousePress() {}

  onMouseRelease() {}

  drawLine(line, num, time) {
    this.ctx.lineWidth = line.width;
    this.ctx.beginPath();
    const points = line.points;

    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      const n = rand.noise2D(
        p.x * this.frequency,
        time * PARAMS.timeScale + num * PARAMS.noiseOffset
      );
      p.y = this.centerY + n * this.amplitude;

      if (i === 0) {
        this.ctx.moveTo(p.x, p.y);
      }
      this.ctx.lineTo(p.x, p.y);
    }

    this.ctx.stroke();
  }

  render(dt, time) {
    this.clear();

    const mouseX = this.mouseNormalized.eased[0];
    const mouseY = this.mouseNormalized.eased[1];

    this.frequency = mapRange(
      mouseX,
      -1,
      1,
      PARAMS.frequencyMin,
      PARAMS.frequencyMax
    );
    this.amplitude = mapRange(
      mouseY,
      -1,
      1,
      0.1 * this.height,
      PARAMS.amplitude * this.height
    );

    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i];
      this.ctx.strokeStyle = line.color;
      this.drawLine(line, i, time);
    }
  }
}
